# =============================================================================
# FILE: backend/api/routes/auth_routes.py
# ROLE: Authentication endpoints
# -----------------------------------------------------------------------------
# POST /register        — create account, returns JWT token
# POST /login           — verify credentials, returns JWT token
# PUT  /user/goal       — update daily calorie goal (JWT required)
#
# All tokens are generated by api/auth.py (PyJWT, 24h expiry)
# Passwords are bcrypt-hashed in user_service.py
# =============================================================================
from flask import Blueprint, jsonify, request

from api.auth import create_token, token_required, get_current_user_id
from services import user_service, session_service

auth_bp = Blueprint("auth", __name__)


@auth_bp.route("/register", methods=["POST"])
def register():
    data = request.get_json() or {}
    name = data.get("name")
    email = data.get("email")
    password = data.get("password")
    daily_goal = data.get("daily_calorie_goal")

    if not name or not email or not password:
        return jsonify({"error": "name, email and password are required"}), 400

    user, error = user_service.register_user(name, email, password, daily_goal)
    if error:
        return jsonify({"error": error}), 409

    token = create_token(user["user_id"], user["name"])
    return jsonify({
        "message": "User registered successfully",
        "user_id": user["user_id"],
        "name": user["name"],
        "token": token,
        "daily_calorie_goal": user["daily_calorie_goal"],
        "role": user["role"],
    }), 201


@auth_bp.route("/login", methods=["POST"])
def login():
    data = request.get_json() or {}
    email = data.get("email")
    password = data.get("password")

    if not email or not password:
        return jsonify({"error": "email and password are required"}), 400

    user = user_service.login_user(email, password)
    if not user:
        return jsonify({"error": "Invalid email or password"}), 401

    token = create_token(user["user_id"], user["name"])
    session_service.start_session(user["user_id"])
    return jsonify({
        "message": "Login successful",
        "user_id": user["user_id"],
        "name": user["name"],
        "token": token,
        "daily_calorie_goal": user["daily_calorie_goal"],
        "role": user["role"],
    }), 200


@auth_bp.route("/user/profile", methods=["GET", "PUT"])
@token_required
def user_profile():
    user_id = get_current_user_id()

    if request.method == "GET":
        user = user_service.get_user_by_id(user_id)
        if not user:
            return jsonify({"error": "User not found"}), 404
        return jsonify({
            "user_id": user["user_id"],
            "name": user["name"],
            "email": user["email"],
            "daily_calorie_goal": user["daily_calorie_goal"],
            "gender": user.get("gender", ""),
            "age": user.get("age", 0),
            "weight": user.get("weight", 0.0),
            "height_feet": user.get("height_feet", 0),
            "height_inch": user.get("height_inch", 0),
            "activity_level": user.get("activity_level", ""),
            "fitness_goal": user.get("fitness_goal", ""),
            "role": user.get("role", "user"),
        }), 200

    data = request.get_json() or {}
    user = user_service.update_profile(
        user_id,
        name=data.get("name"),
        gender=data.get("gender"),
        age=data.get("age"),
        weight=data.get("weight"),
        height_feet=data.get("height_feet"),
        height_inch=data.get("height_inch"),
        activity_level=data.get("activity_level"),
        fitness_goal=data.get("fitness_goal"),
    )
    if not user:
        return jsonify({"error": "User not found"}), 404

    return jsonify({
        "message": "Profile updated successfully",
        "user_id": user["user_id"],
        "name": user["name"],
        "email": user["email"],
        "daily_calorie_goal": user["daily_calorie_goal"],
    }), 200


@auth_bp.route("/user/goal", methods=["PUT"])
@token_required
def update_goal():
    data = request.get_json() or {}
    goal = data.get("daily_calorie_goal")
    if goal is None:
        return jsonify({"error": "daily_calorie_goal is required"}), 400

    user_id = get_current_user_id()
    success = user_service.update_daily_goal(user_id, goal)
    if not success:
        return jsonify({"error": "User not found"}), 404

    return jsonify({
        "message": "Daily calorie goal updated successfully",
        "daily_calorie_goal": goal
    }), 200


@auth_bp.route("/logout", methods=["POST"])
@token_required
def logout():
    user_id = get_current_user_id()
    session_service.end_session(user_id)
    return jsonify({"message": "Logged out successfully"}), 200


@auth_bp.route("/forgot-password", methods=["POST"])
def forgot_password():
    data = request.get_json() or {}
    email = data.get("email")
    new_password = data.get("password")

    if not email or not new_password:
        return jsonify({"error": "email and password are required"}), 400

    user, error = user_service.reset_password(email, new_password)
    if error:
        return jsonify({"error": error}), 404

    return jsonify({"message": "Password updated successfully"}), 200


